mapper.update:
UPDATE POST
SET REPORT_COUNT = (
        SELECT COUNT(*)
        FROM POST_REPORT
        WHERE POST_ID = #{postId}
    ),
    IS_BLIND = CASE
        WHEN (
            SELECT COUNT(*)
            FROM POST_REPORT
            WHERE POST_ID = #{postId}
        ) >= 5 THEN 1
        ELSE IS_BLIND
    END
WHERE POST_ID = #{postId}
  AND IS_DELETED = 0

UPDATE POST_COMMENT
SET CONTENT = #{content}
WHERE COMMENT_ID = #{commentId}

UPDATE POST_COMMENT
SET IS_DELETED = 1
WHERE COMMENT_ID = #{commentId}
